  "claims": [
    {
      "claim": "Galileo's use of the telescope delivered the secrets of the universe to human cognition with the certainty of sense-perception, doing what no one had done before.",
      "claim_type": "author_position",
      "supporting_excerpt": "What Galileo did and what nobody had done before was to use the telescope in such a way that the secrets of the universe were delivered to human cognition “with the certainty of sense-perception”;",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "Prior to Galileo's telescopic discoveries, the philosophical and astronomical speculations of thinkers like Bruno and Copernicus lacked factual confirmation and would have been dismissed as ungrounded imagination.",
      "claim_type": "author_position",
      "supporting_excerpt": "Prior to the telescopic discoveries of Galileo, Giordano Bruno’s philosophy attracted little attention even among learned men, and without the factual confirmation they bestowed upon the Copernican revolution, not only the theologians but all “sensible men . . . would have pronounced it a wild appeal . . . of an uncontrolled imagination.”",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ]
}

